function clumsy(n) {
  const stack = [n];
  let op = 0;
  for (let x = n - 1; x >= 1; x--) {
    if (op === 0) {
      stack.push(stack.pop() * x);
    } else if (op === 1) {
      stack.push(Math.trunc(stack.pop() / x));
    } else if (op === 2) {
      stack.push(x);
    } else {
      stack.push(-x);
    }
    op = (op + 1) % 4;
  }
  let total = 0;
  for (const value of stack) {
    total += value;
  }
  return total;
}

