function clumsy(n) {
  // Write the expression out as tokens, then evaluate it in two passes like a calculator.
  const symbols = ['*', '/', '+', '-'];
  const tokens = [n];
  for (let x = n - 1; x >= 1; x--) tokens.push(symbols[(n - 1 - x) % 4], x);
  const terms = [tokens[0]];
  const signs = ['+'];
  for (let i = 1; i < tokens.length; i += 2) {
    const symbol = tokens[i], value = tokens[i + 1];
    if (symbol === '*') terms[terms.length - 1] *= value;
    else if (symbol === '/') terms[terms.length - 1] = Math.floor(terms[terms.length - 1] / value);
    else { terms.push(value); signs.push(symbol); }
  }
  return terms.reduce((sum, term, i) => (signs[i] === '+' ? sum + term : sum - term), 0);
}

